#!/usr/bin/env python3
"""IoT-Shield: manually provisioned, offline-installing Linux gateway.

Before setup, an administrator must create /var/lib/iot-shield as root:root 0700.
This launcher never creates or repairs that home directory. All pinned Python
wheels (including pip and Requests' transitive dependencies) and public metadata
snapshots are embedded below. Default installation performs no network downloads.
Native Linux tools and Python's venv module must already be present.

Run: sudo /usr/bin/python3 -I /var/lib/iot-shield/IoT-Shield.py
Use --extract-source DIRECTORY to inspect bundled code, wheels, hashes and docs.
"""

from __future__ import annotations

import argparse
import base64
import contextlib
import csv
import ctypes
import ctypes.util
import hashlib
import importlib
import importlib.util
import io
import ipaddress
import json
import logging
import os
import re
import shutil
import signal
import socket
import stat
import subprocess
import sys
import tempfile
import time
import zipfile
from pathlib import Path, PurePosixPath
from types import FrameType, ModuleType
from typing import Any, Iterator
from urllib.parse import urljoin, urlsplit

VERSION = "1.3.0-service"
STATE_BASE = Path("/var/lib/iot-shield")
CONFIG_DEFAULT = Path("/etc/iot-shield/config.json")
RUNTIME_BASE = Path("/run/iot-shield")
SAFE_PATH = "/usr/sbin:/usr/bin:/sbin:/bin"
PYTHON_REQUIREMENTS = ("scapy==2.8.0", "requests==2.33.0")
PINNED_PACKAGES = {
    "pip": "26.2.2", "scapy": "2.8.0", "requests": "2.33.0",
    "certifi": "2026.10.19", "charset-normalizer": "3.5.2",
    "idna": "3.20", "urllib3": "2.7.0",
}
CATALOG_SOURCES = {
    "oui.csv": "https://standards-oui.ieee.org/oui/oui.csv",
    "kev.json": "https://www.cisa.gov/sites/default/files/feeds/known_exploited_vulnerabilities.json",
}
ALLOWED_DATA_HOSTS = {"standards-oui.ieee.org", "www.cisa.gov", "cisa.gov"}


class SetupError(RuntimeError):
    """Report a bounded, actionable installation/configuration failure to the operator."""


class BootstrapTerminated(BaseException):
    """Carry a setup termination signal through finally blocks without being swallowed by error handlers."""

    def __init__(self, signum: int) -> None:
        """Remember SIGTERM/SIGINT so the caller returns the conventional signal-derived exit code."""
        super().__init__(signum)
        self.signum = signum


def setup_signal(signum: int, frame: FrameType | None) -> None:
    """Raise a termination request only; subprocess.run and filesystem/lock finally blocks perform cleanup."""
    raise BootstrapTerminated(signum)


def safe_text(value: Any, limit: int = 2000) -> str:
    """Bound external error output and neutralize terminal control characters and URL credentials."""
    message = "".join(char if char.isprintable() and char != "\x1b" else "?" for char in str(value))
    message = re.sub(r"(https?://)[^/@\s]+:[^/@\s]+@", r"\1[redacted]@", message)
    message = re.sub(r"(?i)([?&](?:api[_-]?key|key|token|access[_-]?token|password|secret)=)[^&#\s]+", r"\1[redacted]", message)
    return message[-limit:]


JOURNAL_SOCKET = "/run/systemd/journal/socket"


def bounded_log_text(value: Any, limit: int = 8000) -> str:
    """Return one printable, bounded log line with common URL credentials/query secrets redacted."""
    message = "".join(c if c.isprintable() and c != "\x1b" else "?" for c in str(value))
    message = re.sub(r"(https?://)[^/@\s]+:[^/@\s]+@", r"\1[redacted]@", message)
    message = re.sub(r"(?i)([?&](?:api[_-]?key|key|token|access[_-]?token|password|secret)=)[^&#\s]+", r"\1[redacted]", message)
    return message[-limit:]


def journal_priority(level: int) -> int:
    """Translate Python severity into the syslog/journald PRIORITY integer without losing ERROR/WARNING."""
    if level >= logging.CRITICAL:
        return 2
    if level >= logging.ERROR:
        return 3
    if level >= logging.WARNING:
        return 4
    if level >= logging.INFO:
        return 6
    return 7


def journal_requested() -> bool:
    """Use native journal transport explicitly, or when stderr really matches systemd's JOURNAL_STREAM."""
    target = os.environ.get("IOT_SHIELD_LOG_TARGET", "auto").lower()
    if target == "journal":
        return True
    if target == "stderr":
        return False
    try:
        status = os.fstat(sys.stderr.fileno())
        return os.environ.get("JOURNAL_STREAM") == f"{status.st_dev}:{status.st_ino}"
    except (AttributeError, OSError, ValueError):
        return False


class JournalOrStderrHandler(logging.Handler):
    """Send bounded native journal datagrams in a service, otherwise use standard StreamHandler.

    Only AF_UNIX is used. Each send has a 50 ms deadline and explicit socket
    cleanup. Failure falls back to stderr with a systemd priority prefix; no
    message is sent through both successful paths, avoiding duplicate journal
    entries. The fallback follows the current sys.stderr, including test captures.
    """

    def __init__(self, identifier: str = "iot-shield") -> None:
        """Retain a fixed syslog identifier and initialize the standard-library fallback handler."""
        super().__init__()
        self.identifier = re.sub(r"[^A-Za-z0-9_.-]", "_", identifier)[:64]
        self.fallback = logging.StreamHandler()
        self.fallback.setFormatter(logging.Formatter("%(message)s"))

    def emit(self, record: logging.LogRecord) -> None:
        """Format/redact one record, send journal fields when requested, and never raise into capture code."""
        connection = None
        message = ""
        requested = journal_requested()
        try:
            message = bounded_log_text(self.format(record))
            priority = journal_priority(record.levelno)
            if requested:
                data = (f"PRIORITY={priority}\nSYSLOG_FACILITY=3\nSYSLOG_IDENTIFIER={self.identifier}\n"
                        f"MESSAGE={message}\n").encode("utf-8")
                connection = socket.socket(socket.AF_UNIX, socket.SOCK_DGRAM)
                connection.settimeout(0.05)
                connection.sendto(data, JOURNAL_SOCKET)
                return
        except Exception:
            # A temporarily unavailable/full journal must not stop inspection.
            if not message:
                message = "iot-shield: ERROR logging formatter/transport unavailable"
        finally:
            if connection is not None:
                try:
                    connection.close()
                except OSError:
                    pass
        try:
            prefix = f"<{journal_priority(record.levelno)}>" if requested else ""
            fallback_record = logging.LogRecord(record.name, record.levelno, record.pathname, record.lineno,
                                                prefix + message, (), None)
            if self.fallback.stream is not sys.stderr:
                # setStream() flushes the previous stream, which might already be closed.
                # Each completed emit was already flushed; switch via a fresh standard handler.
                replacement = logging.StreamHandler(sys.stderr)
                replacement.setFormatter(logging.Formatter("%(message)s"))
                self.fallback.close()
                self.fallback = replacement
            self.fallback.emit(fallback_record)
        except Exception:
            # Even a closed stderr cannot crash gateway workers or recurse into logging.
            return

    def close(self) -> None:
        """Close the fallback handler; there is no persistent journal socket or background log thread."""
        try:
            self.fallback.close()
        finally:
            super().close()


def console_handler(identifier: str = "iot-shield") -> logging.Handler:
    """Return a journal-aware handler; callers select their existing human-readable formatter."""
    return JournalOrStderrHandler(identifier)

def notice(message: str, level: int = logging.INFO) -> None:
    """Emit a bounded standard logging record with a real INFO/WARNING/ERROR journal priority."""
    logger = logging.getLogger("iot-shield.bootstrap")
    if not logger.handlers:
        handler = console_handler()
        handler.setFormatter(logging.Formatter("iot-shield: %(levelname)s %(message)s"))
        logger.addHandler(handler)
        logger.setLevel(logging.INFO)
        logger.propagate = False
    logger.log(level, safe_text(message))


def _open_directory(path: Path, create: bool) -> int:
    """Return a validated directory descriptor using no-follow component traversal.

    Input must be an absolute path without '..'. Newly created children use 0700;
    the designated STATE_BASE is NEVER created or chmodded here. Each opened
    ancestor must have a trusted owner and safe write permissions. Root-owned
    sticky ancestors such as /tmp are permitted. The caller must close the
    returned descriptor. Errors close all intermediate descriptors before raising.
    """
    path = path.absolute()
    if ".." in path.parts:
        raise SetupError("Parent traversal is not permitted in installation/storage paths")
    descriptor = None
    try:
        flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC
        descriptor = os.open("/", flags)
        current = Path("/")
        for component in path.parts[1:]:
            current = current / component
            try:
                child = os.open(component, flags, dir_fd=descriptor)
            except FileNotFoundError:
                if not create or current == STATE_BASE:
                    raise SetupError(f"Required directory is missing: {current}. Create the application home manually as root:root with mode 0700")
                try:
                    os.mkdir(component, mode=0o700, dir_fd=descriptor)
                except FileExistsError:
                    # Re-open and verify a name which appeared during mkdir.
                    child = os.open(component, flags, dir_fd=descriptor)
                else:
                    child = os.open(component, flags, dir_fd=descriptor)
            os.close(descriptor)
            descriptor = child
            status = os.fstat(descriptor)
            if not stat.S_ISDIR(status.st_mode) or status.st_uid not in (0, os.geteuid()):
                raise SetupError("Directory has an untrusted owner or is not a real directory")
            if current == STATE_BASE:
                if status.st_uid != 0 or status.st_gid != 0 or stat.S_IMODE(status.st_mode) != 0o700:
                    raise SetupError(f"{STATE_BASE} must already be root:root with permissions exactly 0700; the script will not repair it")
            sticky_root = status.st_uid == 0 and bool(status.st_mode & stat.S_ISVTX)
            if current != path and status.st_mode & 0o022 and not sticky_root:
                raise SetupError("An installation ancestor is writable by another user")
            if current == path and (status.st_uid != os.geteuid() or status.st_mode & 0o022):
                raise SetupError("Directory has unsafe target ownership or write permissions")
        result, descriptor = descriptor, None
        return result
    except OSError as exc:
        raise SetupError(f"Unsafe or inaccessible directory path ({type(exc).__name__}); symlinks are never followed") from exc
    finally:
        if descriptor is not None:
            os.close(descriptor)


def require_home() -> None:
    """Refuse absent, symlinked or non-root:root-0700 application home; never create/chmod it."""
    descriptor = None
    try:
        descriptor = _open_directory(STATE_BASE, create=False)
    finally:
        if descriptor is not None:
            os.close(descriptor)


def secure_directory(path: Path) -> None:
    """Create only safe child/storage directories; the manually provisioned home is immutable here."""
    path = path.absolute()
    if os.path.normpath(path) in {"/", "/etc", "/var", "/var/lib", "/var/log", "/run", "/tmp", "/opt", "/home", "/usr"}:
        raise SetupError("Use a dedicated subdirectory, not a shared system directory")
    descriptor = None
    try:
        descriptor = _open_directory(path, create=True)
        if path != STATE_BASE:
            os.fchmod(descriptor, 0o700)
    finally:
        if descriptor is not None:
            os.close(descriptor)

@contextlib.contextmanager
def exclusive_lock(path: Path) -> Iterator[None]:
    """Hold a nonblocking, no-follow regular-file lock; always release the descriptor.

    The setup lock serializes installers. The temporary agent lock prevents
    dependency/configuration changes while a gateway instance is already running.
    """
    import fcntl
    secure_directory(path.parent)
    descriptor = None
    try:
        descriptor = os.open(path, os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW | os.O_CLOEXEC, 0o600)
        status = os.fstat(descriptor)
        if not stat.S_ISREG(status.st_mode) or status.st_uid != os.geteuid() or status.st_nlink != 1:
            raise SetupError("Unsafe bootstrap lock file")
        try:
            fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError as exc:
            raise SetupError("Another installer/gateway is running; stop it before configuring or updating") from exc
        yield
    except OSError as exc:
        raise SetupError(f"Cannot acquire/release installation lock: {type(exc).__name__}") from exc
    finally:
        if descriptor is not None:
            os.close(descriptor)


def atomic_write(path: Path, data: bytes) -> None:
    """Atomically write and fsync a private regular file without following a destination symlink."""
    secure_directory(path.parent)
    if path.exists() or path.is_symlink():
        status = path.lstat()
        if not stat.S_ISREG(status.st_mode) or status.st_uid != os.geteuid() or status.st_nlink != 1:
            raise SetupError("Refusing to overwrite an unsafe existing installation/configuration file")
    descriptor, temporary = None, None
    try:
        descriptor, temporary = tempfile.mkstemp(prefix=".iot-shield-", dir=path.parent)
        with os.fdopen(descriptor, "wb") as handle:
            descriptor = None
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
        temporary = None
        directory_fd = os.open(path.parent, os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    except OSError as exc:
        raise SetupError(f"Cannot save private installation/configuration file: {type(exc).__name__}") from exc
    finally:
        if descriptor is not None:
            os.close(descriptor)
        if temporary is not None:
            try:
                os.unlink(temporary)
            except OSError as exc:
                notice(f"Temporary-file cleanup failed ({type(exc).__name__})", logging.WARNING)


def bundled_files() -> dict[str, bytes]:
    """Verify and unpack the embedded archive in RAM, rejecting unsafe paths and oversized members.

    The checksum detects transfer corruption, not malicious changes to this script.
    This is ordinary inspectable source packaging, not a cryptographic signature.
    """
    try:
        archive_bytes = base64.b85decode(BUNDLE_B85)
        if hashlib.sha256(archive_bytes).hexdigest() != BUNDLE_SHA256:
            raise SetupError("Embedded gateway checksum failed; download an intact copy")
        result: dict[str, bytes] = {}
        with zipfile.ZipFile(io.BytesIO(archive_bytes)) as archive:
            members = archive.infolist()
            if len(members) > 80 or sum(info.file_size for info in members) > 32 * 1024 * 1024:
                raise SetupError("Embedded archive exceeds safe extraction bounds")
            for info in members:
                path = PurePosixPath(info.filename)
                if info.is_dir() or path.is_absolute() or ".." in path.parts or "\\" in info.filename or ":" in info.filename or path.as_posix() != info.filename:
                    raise SetupError("Unsafe embedded source path")
                if not path.parts or path.parts[0] not in {"iot_shield", "tests", "deploy", "README.md", "requirements.txt", "config.example.json", "validation-tests.txt", "wheelhouse", "snapshots", "OFFLINE-INSTALL.md"}:
                    raise SetupError("Unexpected embedded source path")
                mode = info.external_attr >> 16
                if stat.S_ISLNK(mode) or info.filename in result or info.file_size > 16 * 1024 * 1024:
                    raise SetupError("Unsafe or duplicate embedded source member")
                result[info.filename] = archive.read(info)
        required = {"iot_shield/__main__.py", "iot_shield/config.py", "wheelhouse/manifest.json",
                    "wheelhouse/requirements-offline.lock", "iot_shield/observability.py", "iot_shield/service_install.py", "snapshots/manifest.json", "snapshots/oui.csv", "snapshots/kev.json"}
        if not required.issubset(result):
            raise SetupError("Embedded offline gateway is incomplete")
        return result
    except (ValueError, OSError, zipfile.BadZipFile, EOFError) as exc:
        raise SetupError(f"Cannot decode embedded gateway: {type(exc).__name__}") from exc


def extract_sources(destination: Path, files: dict[str, bytes]) -> None:
    """Extract/update exact trusted source bytes into private directories; never use extractall()."""
    secure_directory(destination)
    for name, data in files.items():
        path = destination / name
        if path.exists() and not path.is_symlink():
            status = path.stat()
            if stat.S_ISREG(status.st_mode) and status.st_uid == os.geteuid() and status.st_nlink == 1 and not status.st_mode & 0o077 and path.read_bytes() == data:
                continue
        atomic_write(path, data)


def clean_environment() -> dict[str, str]:
    """Return a child environment without Python/library/pip path injection; retain API-key variables."""
    environment = {name: value for name, value in os.environ.items()
                   if not name.startswith(("PYTHON", "PIP_", "LD_"))}
    environment["PATH"] = SAFE_PATH
    environment["PIP_CONFIG_FILE"] = os.devnull
    environment["PIP_NO_INDEX"] = "1"
    environment["NO_COLOR"] = "1"
    environment["TERM"] = "dumb"
    environment["PYTHONNOUSERSITE"] = "1"
    environment["PYTHONDONTWRITEBYTECODE"] = "1"
    return environment


def run_command(command: list[str], label: str, timeout: int = 600) -> subprocess.CompletedProcess[str]:
    """Run a bounded, shell-free package/probe command; log failures with sanitized diagnostics."""
    result = None
    try:
        environment = clean_environment()
        result = subprocess.run(command, capture_output=True, text=True, timeout=timeout,
                                env=environment, check=False)
        if result.returncode:
            detail = safe_text(result.stderr or result.stdout, 1200)
            raise SetupError(f"{label} failed (exit {result.returncode}): {detail}")
        return result
    except (OSError, subprocess.SubprocessError) as exc:
        raise SetupError(f"{label} could not complete ({type(exc).__name__}); check local wheel integrity, native prerequisites, permissions and disk space, then rerun") from exc
    finally:
        result = None


def executable(name: str) -> str | None:
    """Locate only a system executable, not a user-controlled current-directory/PATH replacement."""
    return shutil.which(name, path=SAFE_PATH)


def pcap_available() -> bool:
    """Check that the native passive-capture library loads, without opening a packet socket."""
    library = None
    try:
        filename = ctypes.util.find_library("pcap")
        if filename is None:
            return False
        library = ctypes.CDLL(filename)
        return True
    except (OSError, AttributeError):
        return False
    finally:
        library = None


def venv_modules_available() -> bool:
    """Check stdlib venv support only; ensurepip is unnecessary because pip itself is bundled."""
    try:
        return importlib.util.find_spec("venv") is not None
    except (ImportError, ValueError):
        return False


def check_native_requirements() -> None:
    """Check platform-specific prerequisites locally; never invoke APT, pip indexes or a downloader.

    nftables, iproute2, native libpcap and stdlib venv must be supplied by the
    gateway OS/offline OS media. Portable Python wheels cannot provide kernel
    features, root capabilities or every distro/CPU's native packages.
    """
    missing = []
    for binary, package in (("ip", "iproute2"), ("nft", "nftables")):
        if executable(binary) is None:
            missing.append(package)
    if not pcap_available():
        missing.append("native libpcap")
    if not venv_modules_available():
        missing.append("Python stdlib venv support (distro python3-venv)")
    if missing:
        raise SetupError("Missing OS prerequisites: " + ", ".join(missing) + ". Supply these from the target OS/offline installation media; no network installation was attempted")
    result = run_command([executable("nft") or "/usr/sbin/nft", "--version"], "Native nftables version check", 10)
    version = re.search(r"v([0-9]+)\.([0-9]+)\.([0-9]+)", result.stdout)
    if version is None or tuple(map(int, version.groups())) < (1, 0, 6):
        raise SetupError("nftables 1.0.6+ is required; upgrade it through the target OS before starting")


def validated_wheels(wheelhouse: Path) -> dict[str, Any]:
    """Verify every pinned wheel, including pip, against the trusted embedded manifest and lock.

    Returns the parsed manifest only when all seven packages use architecture-
    independent py3-none-any wheels with matching SHA256 hashes. It also checks
    the exact lock text, so installation cannot silently resolve new dependencies.
    """
    secure_directory(wheelhouse)
    manifest_file = wheelhouse / "manifest.json"
    if manifest_file.is_symlink() or not manifest_file.is_file():
        raise SetupError("Bundled wheel manifest is missing or unsafe")
    manifest = json.loads(manifest_file.read_bytes())
    packages = manifest.get("packages") if isinstance(manifest, dict) else None
    if not isinstance(packages, dict) or set(packages) != set(PINNED_PACKAGES):
        raise SetupError("Offline wheel manifest does not contain the complete pinned dependency set")
    lock = []
    for name, version in sorted(PINNED_PACKAGES.items()):
        record = packages[name]
        if not isinstance(record, dict) or record.get("version") != version:
            raise SetupError("Offline dependency version differs from the approved pin")
        filename, digest = record.get("wheel", ""), record.get("sha256", "")
        if not isinstance(filename, str) or Path(filename).name != filename or not filename.endswith("-py3-none-any.whl"):
            raise SetupError("Offline dependency is not a portable, local pure-Python wheel")
        if not isinstance(digest, str) or not re.fullmatch(r"[0-9a-f]{64}", digest):
            raise SetupError("Offline wheel SHA256 is malformed")
        path = wheelhouse / filename
        status = path.lstat()
        if not stat.S_ISREG(status.st_mode) or status.st_uid != os.geteuid() or status.st_nlink != 1 or status.st_mode & 0o022:
            raise SetupError("Offline wheel has unsafe ownership, permissions, type or hard links")
        if hashlib.sha256(path.read_bytes()).hexdigest() != digest:
            raise SetupError(f"Offline wheel integrity failure: {filename}")
        lock.append(f"{name}=={version} --hash=sha256:{digest}\n")
    lock_file = wheelhouse / "requirements-offline.lock"
    if lock_file.is_symlink() or lock_file.read_text() != "".join(lock):
        raise SetupError("Offline dependency lock does not match its approved wheel hashes")
    return manifest


def venv_ready(directory: Path) -> bool:
    """Verify imports plus exact versions of pip, Scapy, Requests and every transitive dependency."""
    python = directory / "bin" / "python"
    if not python.exists():
        return False
    result = None
    try:
        code = ("import importlib.metadata as m,sys; from pathlib import Path; "
                f"expected={PINNED_PACKAGES!r}; root=Path({str(directory)!r}).resolve(); "
                "assert Path(sys.prefix).resolve()==root and sys.prefix!=sys.base_prefix; "
                "assert all(m.version(k)==v and Path(m.distribution(k).locate_file('')).resolve().is_relative_to(root) "
                "for k,v in expected.items()); import requests; from scapy.all import AsyncSniffer; "
                "assert requests.__version__==expected['requests'] and callable(requests.Session) and callable(AsyncSniffer)")
        result = subprocess.run([str(python), "-I", "-c", code], capture_output=True, text=True,
                                timeout=30, env=clean_environment(), check=False)
        return result.returncode == 0
    except (OSError, subprocess.SubprocessError):
        return False
    finally:
        result = None


def install_python_packages(directory: Path, wheelhouse: Path) -> None:
    """Install/repair a private environment entirely from bundled, SHA256-locked local wheels.

    A venv is created WITHOUT ensurepip. The bundled pip wheel is run directly
    through zipimport and installs itself plus all dependencies with --no-index,
    --find-links, --require-hashes, --only-binary and --no-deps. Global/user pip
    configuration is disabled. Nothing is fetched and system Python is unchanged.
    """
    manifest = validated_wheels(wheelhouse)
    secure_directory(directory)
    if venv_ready(directory):
        notice("Private Python environment verified; offline reinstall not needed")
        return
    python = directory / "bin" / "python"
    notice("Preparing a private environment from bundled wheels; no network will be used")
    # Recreate a failed environment cleanly, including broken/missing dist-info
    # RECORD files which pip cannot otherwise uninstall during a forced repair.
    run_command([sys.executable, "-I", "-m", "venv", "--without-pip", "--clear", str(directory)],
                "Offline private environment creation/repair", 120)
    pip_wheel = wheelhouse / manifest["packages"]["pip"]["wheel"]
    bootstrap = "import runpy,sys; sys.path.insert(0,sys.argv.pop(1)); runpy.run_module('pip',run_name='__main__')"
    run_command([str(python), "-I", "-c", bootstrap, str(pip_wheel), "--isolated", "install",
                 "--disable-pip-version-check", "--no-input", "--no-cache-dir", "--no-color",
                 "--no-index", "--find-links", str(wheelhouse), "--only-binary=:all:", "--require-hashes",
                 "--no-deps", "--force-reinstall", "-r", str(wheelhouse / "requirements-offline.lock")],
                "Offline private Python dependency installation", 600)
    if not venv_ready(directory):
        raise SetupError("Offline dependencies failed import/version checks; no gateway was started")

def in_private_environment(directory: Path) -> bool:
    """Determine whether this process is already using our own verified private venv."""
    try:
        return Path(sys.prefix).resolve() == directory.resolve() and sys.prefix != sys.base_prefix
    except OSError:
        return False


def load_config_module(runtime: Path) -> ModuleType:
    """Import only the trusted bundled standard-library config parser for wizard validation."""
    filename = runtime / "iot_shield" / "config.py"
    specification = importlib.util.spec_from_file_location("_iot_shield_singlefile_config", filename)
    if specification is None or specification.loader is None:
        raise SetupError("Cannot load the bundled configuration validator")
    module = importlib.util.module_from_spec(specification)
    sys.modules[specification.name] = module
    specification.loader.exec_module(module)
    return module


def default_config(files: dict[str, bytes], arguments: argparse.Namespace) -> dict[str, Any]:
    """Create a model-independent default-deny configuration, with no fake sample device entries."""
    data = json.loads(files["config.example.json"])
    data["devices"] = []
    data["state_dir"] = str(STATE_BASE)
    data["log_dir"] = "/var/log/iot-shield"
    data["oui_file"] = str(STATE_BASE / "data" / "oui.csv")
    data["audit"]["kev_file"] = str(STATE_BASE / "data" / "kev.json")
    if arguments.iot_interface:
        data["iot_interface"] = arguments.iot_interface
    if arguments.uplink_interface:
        data["uplink_interface"] = arguments.uplink_interface
    if arguments.gateway_cidr:
        try:
            interface = ipaddress.IPv4Interface(arguments.gateway_cidr)
        except ValueError as exc:
            raise SetupError("--gateway-cidr must be a usable private IPv4/prefix, such as 10.42.0.1/24") from exc
        data["gateway_ipv4"], data["iot_network"] = str(interface.ip), str(interface.network)
    return data


def prompt(label: str, default: str = "", required: bool = False) -> str:
    """Read a bounded terminal answer or raise on EOF/control characters; never guess device trust."""
    suffix = f" [{default}]" if default else ""
    answer = input(label + suffix + ": ").strip() or default
    if len(answer) > 512 or any(ord(char) < 32 or ord(char) == 127 for char in answer):
        raise SetupError("Terminal response contains invalid characters or is too long")
    if required and not answer:
        raise SetupError(f"{label} is required")
    return answer


def yes(label: str, default: bool = False) -> bool:
    """Read an explicit yes/no decision, defaulting to the least-permissive choice."""
    value = prompt(label + " (yes/no)", "yes" if default else "no").lower()
    if value not in {"yes", "y", "no", "n"}:
        raise SetupError("Please answer yes or no")
    return value in {"yes", "y"}


def ports(value: str) -> list[int]:
    """Parse a bounded comma-separated list of TCP/UDP ports; final validation rejects external DNS."""
    if not value:
        return []
    values = value.split(",")
    if len(values) > 32 or any(not re.fullmatch(r"[0-9]{1,5}", item.strip()) for item in values):
        raise SetupError("Use at most 32 comma-separated port numbers")
    checked = sorted({int(item.strip()) for item in values})
    if any(not 1 <= item <= 65535 for item in checked):
        raise SetupError("Ports must be between 1 and 65535")
    return checked


def enroll_device(data: dict[str, Any], validator: ModuleType) -> None:
    """Add any trusted MAC/IP device, regardless of model, using explicitly supplied manufacturer domains.

    The device is not probed. Manufacturer endpoint approval is an administrator
    decision, never inferred from an OUI or from the device's own DNS requests.
    Duplicate identities or incorrect IPs are rejected by the full config parser.
    """
    mac = validator.normalize_mac(prompt("Device MAC address", required=True))
    if any(device["mac"] == mac for device in data["devices"]):
        raise SetupError("This MAC is already configured; edit its existing policy instead of duplicating it")
    name = prompt("Device name", mac)
    address = str(ipaddress.IPv4Address(prompt("Reserved device IPv4 address", required=True)))
    manufacturer = prompt("Trusted manufacturer (optional)")
    product = prompt("Trusted product/model (optional)")
    firmware = prompt("Firmware version (optional)")
    raw_domains = prompt("Exact approved manufacturer domains, comma-separated (empty = deny all)")
    domains = [validator.normalize_domain(item.strip()) for item in raw_domains.split(",") if item.strip()]
    if len(domains) > 16:
        raise SetupError("A device supports at most 16 exact endpoints")
    tcp = ports(prompt("TCP ports for those domains", "443")) if domains else []
    udp = ports(prompt("UDP ports for those domains (optional)")) if domains else []
    device = {"mac": mac, "name": name, "ipv4": [address], "manufacturer": manufacturer,
              "product": product, "firmware": firmware, "support_end": None, "public_ip": None,
              "endpoints": [{"domain": domain, "tcp_ports": tcp, "udp_ports": udp} for domain in domains]}
    data["devices"].append(device)
    notice("This reserved IP must match your existing DHCP reservation/static device address")


def configure(data: dict[str, Any], arguments: argparse.Namespace, validator: ModuleType) -> None:
    """Interactively set existing gateway roles or enroll devices, without readdressing any interface."""
    if not sys.stdin.isatty():
        raise SetupError("The configuration wizard needs a terminal; otherwise supply an existing --config JSON file")
    print("\nIoT-Shield setup — writes policy only; does not configure an AP or change network addresses.")
    print("This is an IPv4 routed gateway. Unknown devices stay default-deny. Encrypted payloads remain opaque.")
    if not arguments.enroll:
        data["iot_interface"] = prompt("Existing IoT/AP interface", data["iot_interface"])
        data["uplink_interface"] = prompt("Existing separate uplink interface", data["uplink_interface"])
        interface = ipaddress.IPv4Interface(prompt("Existing gateway IPv4/prefix", f"{data['gateway_ipv4']}/{ipaddress.IPv4Network(data['iot_network']).prefixlen}"))
        data["gateway_ipv4"], data["iot_network"] = str(interface.ip), str(interface.network)
    add = True if arguments.enroll else yes("Enroll a trusted device now?", False)
    while add:
        enroll_device(data, validator)
        add = yes("Enroll another device?", False)


def prepare_config(runtime: Path, files: dict[str, bytes], arguments: argparse.Namespace) -> Path:
    """Load or atomically create validated policy; never overwrite an existing config just by running."""
    path = arguments.config.expanduser().absolute()
    validator = load_config_module(runtime)
    existed = path.exists() or path.is_symlink()
    if existed:
        validator.Config.load(path)
        with path.open("r", encoding="utf-8") as handle:
            data = json.load(handle)
        if any((arguments.iot_interface, arguments.uplink_interface, arguments.gateway_cidr)):
            raise SetupError("Interface override flags apply only when creating a new configuration; use --configure to modify an existing policy")
    else:
        data = default_config(files, arguments)
    wizard = arguments.configure or arguments.enroll or (not existed and sys.stdin.isatty() and not arguments.setup_only)
    if wizard:
        configure(data, arguments, validator)
    if not existed or wizard:
        validator.Config.from_dict(data, path.parent)
        atomic_write(path, (json.dumps(data, indent=2, ensure_ascii=True) + "\n").encode())
        notice(f"Configuration saved to {path}; authorized identities: {len(data['devices'])}")
        if not data["devices"]:
            notice("No devices are authorized yet. Discovery is generic; ALL unknown devices remain default-deny")
    return path


def validate_catalog(name: str, content: bytes) -> None:
    """Validate public OUI/KEV data before atomic replacement; never execute downloaded content."""
    if name == "kev.json":
        data = json.loads(content)
        entries = data.get("vulnerabilities") if isinstance(data, dict) else None
        if not isinstance(entries, list) or not 1 <= len(entries) <= 50000:
            raise SetupError("Downloaded CISA catalog has an invalid schema")
        for row in entries:
            if not isinstance(row, dict) or not re.fullmatch(r"CVE-[0-9]{4}-[0-9]{4,9}", str(row.get("cveID", ""))) or not isinstance(row.get("vendorProject"), str) or not isinstance(row.get("product"), str):
                raise SetupError("Downloaded CISA catalog contains an invalid entry")
    elif name == "oui.csv":
        reader = csv.DictReader(io.StringIO(content.decode("utf-8-sig")))
        if not {"Assignment", "Organization Name"}.issubset(set(reader.fieldnames or [])):
            raise SetupError("Downloaded IEEE OUI CSV has an invalid header")
        if not any(re.fullmatch(r"[0-9A-Fa-f]{6}", row.get("Assignment", "")) for row in reader):
            raise SetupError("Downloaded IEEE OUI data contains no 24-bit assignments")
    else:
        raise SetupError("Unknown public catalog name")


def download_catalog(name: str, filename: Path) -> bool:
    """Download one public HTTPS-only, host-restricted, size/time-bounded catalog using requests.

    Returns False on network/schema/storage failure, preserving any previous file.
    No device signatures, addresses or credentials are sent to these public feeds.
    Failure reduces identification/intelligence coverage, never relaxes firewall policy.
    """
    import requests
    response, session, content = None, None, bytearray()
    try:
        session = requests.Session()
        session.trust_env = False
        url, deadline = CATALOG_SOURCES[name], time.monotonic() + 90
        for _ in range(4):
            target = urlsplit(url)
            if target.scheme != "https" or target.hostname not in ALLOWED_DATA_HOSTS or target.username or target.password:
                raise SetupError("Public catalog redirected outside the approved HTTPS hosts")
            response = session.get(url, timeout=(3, 6), stream=True, allow_redirects=False,
                                   headers={"User-Agent": "IoT-Shield/1.3 explicit-public-catalog-refresh"})
            if response.status_code in (301, 302, 303, 307, 308):
                location = response.headers.get("Location")
                if not location:
                    raise SetupError("Catalog redirect has no Location")
                url = urljoin(url, location)
                response.close()
                response = None
                if time.monotonic() > deadline:
                    raise SetupError("Catalog redirect deadline exceeded")
                continue
            if response.status_code != 200:
                raise SetupError(f"Catalog HTTP status {response.status_code}")
            # Single-byte streaming lets a wall-clock check stop slow-drip responses.
            for chunk in response.iter_content(1):
                content.extend(chunk)
                if len(content) > 16 * 1024 * 1024 or time.monotonic() > deadline:
                    raise SetupError("Catalog exceeds size/time limits")
            validate_catalog(name, bytes(content))
            atomic_write(filename, bytes(content))
            notice(f"Public catalog ready: {name}")
            return True
        raise SetupError("Too many catalog redirects")
    except (requests.RequestException, OSError, ValueError, SetupError, csv.Error) as exc:
        reason = str(exc) if isinstance(exc, SetupError) else type(exc).__name__
        notice(f"{name} unavailable ({reason}); vendor/CVE coverage may be incomplete, policy is unchanged", logging.WARNING)
        return False
    finally:
        content.clear()
        if response is not None:
            response.close()
        if session is not None:
            session.close()


def seed_catalogs(files: dict[str, bytes]) -> None:
    """Install verified bundled OUI/KEV snapshots only when no cached file exists; never use the network."""
    directory = STATE_BASE / "data"
    secure_directory(directory)
    manifest = json.loads(files["snapshots/manifest.json"])
    for name in CATALOG_SOURCES:
        filename = directory / name
        if filename.is_symlink():
            raise SetupError("Public metadata cache must not contain symlinks")
        content = files["snapshots/" + name]
        record = manifest["files"][name]
        if hashlib.sha256(content).hexdigest() != record["sha256"]:
            raise SetupError("Bundled metadata snapshot checksum failed")
        if not filename.exists():
            validate_catalog(name, content)
            atomic_write(filename, content)
    notice("Bundled/cached OUI and KEV data ready; no automatic network refresh")


def refresh_catalogs(arguments: argparse.Namespace, files: dict[str, bytes]) -> None:
    """Always seed offline metadata; contact public feeds ONLY with explicit --refresh-data."""
    seed_catalogs(files)
    if not arguments.refresh_data:
        return
    directory = STATE_BASE / "data"
    for name in CATALOG_SOURCES:
        notice(f"Explicit online metadata refresh requested: {name}")
        download_catalog(name, directory / name)

def parser() -> argparse.ArgumentParser:
    """Build a standard-library CLI; launch installs only the bundled Python dependencies."""
    result = argparse.ArgumentParser(
        description="IoT-Shield: offline Python installer and default-deny IPv4 Linux gateway",
        epilog="Requires a manually created root:root 0700 home, Python 3.10+/venv, nftables, iproute2, libpcap and an existing routed Linux gateway. Python installation is offline; universal IoT support is not claimed.")
    result.add_argument("--version", action="version", version=f"IoT-Shield {VERSION}")
    result.add_argument("--config", type=Path, default=CONFIG_DEFAULT, help="policy JSON; created safely if missing")
    result.add_argument("--configure", action="store_true", help="interactive gateway-role and device policy wizard")
    result.add_argument("--enroll", action="store_true", help="enroll a trusted MAC/reserved-IP/manufacturer-domain policy, then exit")
    result.add_argument("--iot-interface", help="IoT interface for a NEW config (default wlan0)")
    result.add_argument("--uplink-interface", help="uplink interface for a NEW config (default eth0)")
    result.add_argument("--gateway-cidr", help="existing IPv4/prefix for a NEW config (default 10.42.0.1/24)")
    result.add_argument("--install-service", action="store_true", help="validate, install and enable hardened systemd units/guard; never start them")
    result.add_argument("--replace-service", action="store_true", help="with --install-service only: back up and replace different existing managed files")
    result.add_argument("--setup-only", action="store_true", help="install Python dependencies from bundled wheels; no capture or firewall changes")
    result.add_argument("--no-data", action="store_true", help="compatibility flag: keep all metadata refreshes offline (already the default)")
    result.add_argument("--refresh-data", action="store_true", help="explicitly allow ONLINE IEEE/CISA metadata refresh; never needed for installation")
    result.add_argument("--verify-home", action="store_true", help="only verify the pre-created home; no extraction/install/network")
    result.add_argument("--no-cli", action="store_true", help="run the gateway headlessly")
    result.add_argument("--check", action="store_true", help="check native prerequisites, install Python wheels offline and validate topology without changing nft rules")
    result.add_argument("--extract-source", type=Path, metavar="DIRECTORY", help="extract all bundled code/docs/tests without installing; no root needed")
    return result


def main(argv: list[str] | None = None) -> int:
    """Validate manual provisioning, install local wheels, re-exec privately and launch the gateway.

    --setup-only/--enroll never start the gateway. Normal execution still needs
    correct existing AP/routing/isolation and approved per-device destinations.
    Bootstrap failures are descriptive and leave existing firewall policy alone.
    """
    arguments = parser().parse_args(argv)
    previous_signals: dict[int, Any] = {}
    if arguments.replace_service and not arguments.install_service:
        notice("--replace-service requires --install-service", logging.ERROR)
        return 2
    if arguments.install_service and (arguments.check or arguments.enroll or arguments.extract_source or arguments.verify_home):
        notice("--install-service cannot be combined with --check/--enroll/--extract-source/--verify-home", logging.ERROR)
        return 2
    if arguments.install_service:
        arguments.setup_only = True
    if arguments.no_data and arguments.refresh_data:
        notice("--no-data and --refresh-data cannot be combined", logging.ERROR)
        return 2
    try:
        if arguments.extract_source:
            destination = arguments.extract_source.absolute()
            extract_sources(destination, bundled_files())
            atomic_write(destination / "IoT-Shield.py", Path(__file__).absolute().read_bytes())
            notice(f"Full inspectable source extracted to {destination}; no dependencies installed")
            return 0
        if sys.version_info < (3, 10):
            raise SetupError("Python 3.10+ is required to run this file; a Python script cannot run before its interpreter exists")
        if sys.platform != "linux" or not hasattr(os, "geteuid"):
            raise SetupError("This is a Linux routed gateway, not a Windows/macOS/Bluetooth/Zigbee agent")
        if os.geteuid() != 0:
            raise SetupError("Run with sudo/root: raw network sockets require CAP_NET_RAW, nftables requires CAP_NET_ADMIN, DNS uses privileged port 53, and the installation home must be root-owned")
        require_home()
        if arguments.verify_home:
            notice(f"Home verified: {STATE_BASE}, owner root:root, permissions 0700")
            return 0
        previous_signals = {sig: signal.signal(sig, setup_signal) for sig in (signal.SIGTERM, signal.SIGINT)}
        # A Type=simple unit is visible during bootstrap; an early reload must not kill setup.
        # SIG_IGN survives the private interpreter exec; Application takes ownership when ready.
        previous_signals[signal.SIGHUP] = signal.signal(signal.SIGHUP, signal.SIG_IGN)
        os.umask(0o077)
        os.environ["PATH"] = SAFE_PATH
        os.environ["NO_COLOR"] = "1"
        os.environ["TERM"] = "dumb"
        sys.dont_write_bytecode = True
        files = bundled_files()
        install_base = STATE_BASE / "bootstrap"
        runtime = install_base / "releases" / BUNDLE_SHA256[:20]
        environment = install_base / "venv"
        next_command: list[str] | None = None
        with exclusive_lock(RUNTIME_BASE / "setup.lock"), exclusive_lock(RUNTIME_BASE / "agent.lock"):
            secure_directory(STATE_BASE)
            check_native_requirements()
            extract_sources(runtime, files)
            install_python_packages(environment, runtime / "wheelhouse")
            if not in_private_environment(environment):
                launcher = runtime / "IoT-Shield.py"
                atomic_write(launcher, Path(__file__).absolute().read_bytes())
                next_command = [str(environment / "bin" / "python"), "-I", "-u", str(launcher), *(sys.argv[1:] if argv is None else argv)]
            else:
                config_path = prepare_config(runtime, files, arguments)
                refresh_catalogs(arguments, files)
                if arguments.install_service:
                    sys.path.insert(0, str(runtime))
                    installer_module = importlib.import_module("iot_shield.service_install")
                    service_logger = logging.getLogger("iot-shield.bootstrap")
                    if not service_logger.handlers:
                        notice("Preparing explicit systemd installation; no network downloads or service starts")
                    installer = installer_module.ServiceInstaller(STATE_BASE, CONFIG_DEFAULT.parent, Path("/var/log/iot-shield"),
                        Path("/etc/systemd/system"), Path(__file__).absolute(), files, service_logger)
                    installer.install(config_path, arguments.replace_service)
                    notice("Services enabled, NOT started. Review AP/forwarding ordering, then: systemctl start iot-shield-guard.service iot-shield.service")
        if next_command is not None:
            notice("Restarting automatically inside the private environment")
            try:
                os.execve(next_command[0], next_command, clean_environment())
            except OSError as exc:
                raise SetupError(f"Private interpreter could not start ({type(exc).__name__})") from exc
            finally:
                next_command = None
        if arguments.setup_only or arguments.enroll:
            notice(f"Setup complete. Policy: {config_path}. Python installation used bundled wheels only; rerun this file or start the systemd service")
            return 0
        notice("Starting all gateway modules. Unknown devices stay blocked; AP/IP routing and isolation must already be configured")
        sys.path.insert(0, str(runtime))
        engine = importlib.import_module("iot_shield.__main__")
        engine_arguments = ["--config", str(config_path)]
        if arguments.no_cli:
            engine_arguments.append("--no-cli")
        if arguments.check:
            engine_arguments.append("--check")
        return int(engine.main(engine_arguments))
    except BootstrapTerminated as exc:
        notice(f"Setup terminated by signal {exc.signum}; child processes and private locks cleaned up", logging.WARNING)
        return 128 + exc.signum
    except KeyboardInterrupt:
        notice("Setup interrupted; no permissive firewall fallback was created", logging.WARNING)
        return 130
    except EOFError:
        notice("Configuration input ended; rerun from a terminal or provide --config", logging.ERROR)
        return 2
    except (RuntimeError, OSError, ValueError, ImportError) as exc:
        notice(f"Cannot start: {safe_text(str(exc), 1500)}", logging.ERROR)
        return 1
    except Exception as exc:
        notice(f"Unexpected setup failure ({type(exc).__name__}); no automatic allow-all fallback exists", logging.ERROR)
        return 1
    finally:
        for signum, handler in previous_signals.items():
            signal.signal(signum, handler)


